var a=`1145-new-york-cheesecake`;var t=`world-1145`;var i=`US`;var n=`northern-america`;var s=8;var o=335;var h={en:`New York Cheesecake`,ua:`Нью-йоркський чизкейк`};var g={en:`New York Cheesecake is a dish from United States prepared with graham cracker crumbs, cream cheese, chicken egg, sour cream. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Нью-йоркський чизкейк, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: крихта крекера грем, вершковий сир, куряче яйце, сметана. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var c=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`graham-cracker-crumbs`,290,`g`],[`unsalted-butter`,110,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:12,i:[[`cream-cheese`,870,`g`],[`white-granulated-sugar`,250,`g`],[`chicken-egg`,4,`pcs`],[`sour-cream`,180,`g`],[`vanilla-extract`,8,`ml`]]},{en:`Bake the cheesecake gently around 150–160°C, preferably in a water bath, until edges set and the center still has a slight wobble; cool gradually to avoid cracks.`,ua:`Печіть чизкейк делікатно при 150–160°C, бажано на водяній бані, доки краї схопляться, а середина ще трохи тремтітиме; охолоджуйте поступово, щоб уникнути тріщин.`,t:[`water-bath-baking`],m:65,i:[]},{en:`Refrigerate the prepared mixture for about 240 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 240 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:240,i:[]}];var l={slug:a,id:t,country:`US`,region:n,servings:8,minutes:335,title:h,text:g,steps:c};export{i as country,l as default,t as id,o as minutes,n as region,s as servings,a as slug,c as steps,g as text,h as title};